// GENERATED by port-tests.py from ../xb-chat/test: the Node tests, run against the Rust server.
// The browser stack (web/js) against the real server over a real WebSocket,
// talking to a TCP client. Runs in Node, which has WebSocket + WebCrypto.

import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { promises as fs } from 'node:fs';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { after, before, describe, test } from 'node:test';
import { startRust } from './rust.js';
import { Client } from '../../xb-chat/clients/node/client.js';
import { WebClient } from '../../xb-chat/clients/web/js/client.js';
import { generateKeyPair } from '../../xb-chat/clients/web/js/noise.js';

let dir, chat, media, web, base, wsUrl;
const open = [];

before(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), 'xb-web-'));
  // Host the web app the way server/main.js does.
  chat = await startRust({ dir, appDir: path.resolve(import.meta.dirname, '../../xb-chat/clients/web') });
  media = chat.media;
  base = chat.base;
  wsUrl = chat.wsUrl;
});

after(async () => {
  for (const c of open) c.close();
  await chat.close();
  await fs.rm(dir, { recursive: true, force: true });
});

const next = (em, ev, filter = () => true, ms = 3000) =>
  new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`timed out waiting for ${ev}`)), ms);
    const on = (v) => {
      if (!filter(v)) return;
      clearTimeout(timer);
      em.off(ev, on);
      resolve(v);
    };
    em.on(ev, on);
  });

async function webClient(keyPair) {
  const c = new WebClient({ url: wsUrl, staticKeyPair: keyPair || (await generateKeyPair()), mediaBase: base, serverPublicKey: chat.publicKey });
  c.on('error', () => {});
  open.push(c);
  await c.connect();
  return c;
}

async function tcpClient(user, register = false) {
  const c = new Client({ port: chat.port, serverPublicKey: chat.publicKey });
  c.on('error', () => {});
  open.push(c);
  await c.connect();
  await (register ? c.register(user, 'password1') : c.login(user, 'password1'));
  return c;
}

describe('web client over WebSocket', () => {
  let deviceKey;

  test('registers as a linked device and chats with a TCP client', async () => {
    deviceKey = await generateKeyPair();
    const w = await webClient(deviceKey);
    await w.register('webby', 'password1', { remember: true, device: 'Chrome on Windows' });
    const tcp = await tcpClient('tcpuser', true);

    const atTcp = next(tcp, 'message');
    const delivered = next(w, 'receipt', (r) => r.type === 'delivered');
    const ack = await w.sendMessage('tcpuser@s.xb', 'hello from the browser 👋');
    const m = await atTcp;
    assert.equal(m.text, 'hello from the browser 👋');
    assert.equal(m.from, 'webby@s.xb');
    assert.equal((await delivered).id, ack.id);

    const atWeb = next(w, 'message');
    await tcp.sendMessage('webby', 'hello from the terminal');
    assert.equal((await atWeb).text, 'hello from the terminal');

    const big = 'line of stock data, '.repeat(1000);
    const atTcp2 = next(tcp, 'message');
    await w.sendMessage('tcpuser@s.xb', big);
    assert.equal((await atTcp2).text, big, 'compressed in the browser, inflated by node');
    w.close();
    tcp.close();
  });

  test('logs back in with the device key alone, and only with it', async () => {
    const w = await webClient(deviceKey);
    const { jid } = await w.loginDevice('webby');
    assert.equal(jid, 'webby@s.xb');
    const devices = await w.listDevices();
    assert.equal(devices.length, 1);
    assert.equal(devices[0].name, 'Chrome on Windows');
    assert.ok(devices[0].current);
    w.close();

    const stranger = await webClient(); // a different key
    await assert.rejects(stranger.loginDevice('webby'), { code: 'not-authorized' });
    stranger.close();
  });

  test('media between browser and TCP client, both directions', async () => {
    const w = await webClient(deviceKey);
    await w.loginDevice('webby');
    const tcp = await tcpClient('tcpuser');
    const photo = new Uint8Array(randomBytes(50_000));

    const atTcp = next(tcp, 'message');
    await w.sendMedia('tcpuser@s.xb', photo, { mimetype: 'image/png', caption: 'from web' });
    const m = await atTcp;
    assert.equal(m.media.caption, 'from web');
    assert.ok((await tcp.downloadMedia(m.media)).equals(Buffer.from(photo)));

    const atWeb = next(w, 'message');
    await tcp.sendMedia('webby', Buffer.from(photo), { mimetype: 'image/jpeg' });
    const back = await atWeb;
    assert.deepEqual(await w.downloadMedia(back.media), photo);
    w.close();
    tcp.close();
  });

  test('expired media: the receiver asks the sender to upload it again (media-retry)', async () => {
    const w = await webClient(deviceKey);
    await w.loginDevice('webby');
    const tcp = await tcpClient('tcpuser');
    const photo = new Uint8Array(randomBytes(40_000));

    const atTcp = next(tcp, 'message');
    const sent = await w.sendMedia('tcpuser@s.xb', photo, { mimetype: 'image/jpeg' });
    const m = await atTcp;
    // The file leaves the server (30 days later).
    await fs.rm(path.join(dir, 'media', m.media.sha256));
    await assert.rejects(tcp.downloadMedia(m.media), /404/);

    // The sender's side, as in the web app: upload its copy again, answer with the new attributes.
    // (Not awaited inside the handler: it runs under the decrypt lock, and sending needs it.)
    const asked = new Promise((resolve) => {
      w.protocolHandler = (p) => p.type === 'media-retry' && resolve(p);
    });
    asked.then(async (p) => {
      assert.equal(p.from, 'tcpuser@s.xb');
      assert.equal(p.id, sent.id);
      const up = await w.uploadMedia(photo, {});
      await w.sendProtocolTo(p.from, { type: 'media-retry-ok', id: p.id, chat: p.chat, url: up.url, sha256: up.sha256, key: up.key, size: String(up.size) });
    });
    const answer = next(tcp, 'protocol', (p) => p.type === 'media-retry-ok');
    await tcp.sendEncrypted('webby@s.xb', [{ tag: 'protocol', attrs: { type: 'media-retry', id: m.id, chat: m.chat, sha256: m.media.sha256 } }]);
    const ok = await answer;
    assert.equal(ok.from, 'webby@s.xb');
    assert.notEqual(ok.key, m.media.key, 'uploaded again with a new key');
    assert.ok((await tcp.downloadMedia({ ...m.media, url: ok.url, sha256: ok.sha256, key: ok.key })).equals(Buffer.from(photo)));
    w.close();
    tcp.close();
  });

  test('media: progress, cancel, and thumbnail / size / name inside the encrypted message', async () => {
    const w = await webClient(deviceKey);
    await w.loginDevice('webby');
    const tcp = await tcpClient('tcpuser');
    const photo = new Uint8Array(randomBytes(80_000));

    // Cancelled before it starts: nothing is uploaded.
    const ctrl = new AbortController();
    ctrl.abort();
    await assert.rejects(w.uploadEncrypted(await w.encryptMedia(photo), { signal: ctrl.signal }));

    const progress = [];
    const media = await w.uploadMedia(photo, {
      mimetype: 'image/jpeg',
      type: 'image',
      name: 'shelf.jpg',
      thumbnail: 'AAEC',
      width: 1600,
      height: 1200,
      onProgress: (p) => progress.push(p),
    });
    assert.equal(progress.at(-1), 1);
    const atTcp = next(tcp, 'message');
    await w.forwardMedia('tcpuser@s.xb', { ...media, caption: 'shelf 4' });
    const m = await atTcp;
    assert.deepEqual(
      { name: m.media.name, type: m.media.type, thumbnail: m.media.thumbnail, width: m.media.width, height: m.media.height, caption: m.media.caption },
      { name: 'shelf.jpg', type: 'image', thumbnail: 'AAEC', width: '1600', height: '1200', caption: 'shelf 4' },
    );
    assert.ok((await tcp.downloadMedia(m.media)).equals(Buffer.from(photo)));

    const down = [];
    assert.deepEqual(await w.downloadMedia(media, { onProgress: (p) => down.push(p) }), photo);
    assert.equal(down.at(-1), 1);
    w.close();
    tcp.close();
  });

  test('replies (quoted messages) and forwards, both directions', async () => {
    const w = await webClient(deviceKey);
    await w.loginDevice('webby');
    const tcp = await tcpClient('tcpuser');

    const atWeb = next(w, 'message');
    const orig = await tcp.sendMessage('webby', 'which shelf?');
    const first = await atWeb;
    assert.equal(first.quote, undefined);
    assert.equal(first.forwarded, undefined);

    // The browser replies to it; the preview is cut to 200 characters.
    const quote = { id: orig.id, from: 'tcpuser@s.xb', kind: 'text', text: `which shelf?${' '.repeat(300)}` };
    const atTcp = next(tcp, 'message');
    await w.sendMessage('tcpuser@s.xb', 'shelf 4', { quote });
    const reply = await atTcp;
    assert.equal(reply.text, 'shelf 4');
    assert.deepEqual(reply.quote, { id: orig.id, from: 'tcpuser@s.xb', kind: 'text', text: quote.text.slice(0, 200) });
    assert.equal(reply.forwarded, undefined);

    // The terminal replies to a photo, with its thumbnail; the browser sees it.
    const atWeb2 = next(w, 'message');
    const photoQuote = { id: 'PHOTO1', from: 'webby@s.xb', kind: 'image', text: '', thumbnail: 'AAEC' };
    await tcp.sendMessage('webby', 'nice', { quote: photoQuote });
    assert.deepEqual((await atWeb2).quote, photoQuote);

    // Forwarding text and a file (no new upload) from the browser.
    const atTcp2 = next(tcp, 'message');
    await w.sendMessage('tcpuser@s.xb', 'shelf 4', { forwarded: true });
    const fwd = await atTcp2;
    assert.equal(fwd.text, 'shelf 4');
    assert.equal(fwd.forwarded, true);
    assert.equal(fwd.quote, undefined);

    const photo = new Uint8Array(randomBytes(20_000));
    const media = await w.uploadMedia(photo, { mimetype: 'image/jpeg', type: 'image', caption: 'shelf 4' });
    const atTcp3 = next(tcp, 'message');
    await w.forwardMedia('tcpuser@s.xb', media, { forwarded: true });
    const fwdMedia = await atTcp3;
    assert.equal(fwdMedia.forwarded, true);
    assert.equal(fwdMedia.media.caption, 'shelf 4');
    assert.ok((await tcp.downloadMedia(fwdMedia.media)).equals(Buffer.from(photo)));

    // And from the terminal to the browser.
    const atWeb3 = next(w, 'message');
    await tcp.forwardMedia('webby', fwdMedia.media, { forwarded: true });
    const back = await atWeb3;
    assert.equal(back.forwarded, true);
    assert.deepEqual(await w.downloadMedia(back.media), photo);
    w.close();
    tcp.close();
  });

  test('unlinking the device stops key-only login', async () => {
    const w = await webClient(deviceKey);
    await w.loginDevice('webby');
    const [d] = await w.listDevices();
    // Unlinking yourself: the server drops this connection right away, and
    // the close can beat the iq result. Either way the device is gone.
    await w.unlinkDevice(d.key).catch((err) => assert.equal(err.code, 'disconnected'));
    w.close();
    const again = await webClient(deviceKey);
    await assert.rejects(again.loginDevice('webby'), { code: 'not-authorized' });
    again.close();
  });
});

describe('web server', () => {
  test('serves the app with security headers and the shared dictionary', async () => {
    const res = await fetch(`${base}/`);
    assert.equal(res.status, 200);
    assert.match(res.headers.get('content-security-policy'), /default-src 'self'/);
    assert.match(await res.text(), /<html/i);
    const tok = await fetch(`${base}/shared/tokens.js`);
    assert.match(await tok.text(), /SINGLE_BYTE_TOKENS/);
  });

  test('refuses path traversal', async () => {
    for (const p of ['/..%2Fpackage.json', '/%2e%2e/server/store.js', '/js/..%2F..%2Fpackage.json']) {
      assert.equal((await fetch(`${base}${p}`)).status, 404, p);
    }
  });

  test('rejects WebSocket upgrades from other sites', async () => {
    const status = await new Promise((resolve) => {
      const s = net.connect(chat.webPort, '127.0.0.1', () => {
        s.write(
          `GET /ws HTTP/1.1\r\nHost: 127.0.0.1:${chat.webPort}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n` +
            'Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\nOrigin: https://evil.example\r\n\r\n',
        );
      });
      s.once('data', (d) => resolve(d.toString().split(' ')[1]));
    });
    assert.equal(status, '403');
  });
});
